import { OpsRestaurantSettingsClient } from '@/components/features/restaurant-settings/OpsRestaurantSettingsClient';

import type { Metadata } from 'next';

export const metadata: Metadata = {
  title: 'Restaurant profile · Nab a Table Ops',
  description: 'Manage public restaurant details, booking rules, team alerts, and discovery.',
};

export default function RestaurantProfileSettingsPage() {
  return <OpsRestaurantSettingsClient view="profile" />;
}

import { redirect } from 'next/navigation';

import { RestaurantSettingsPageShell } from '@/components/features/restaurant-settings/RestaurantSettingsPageShell';
import { withRedirectedFrom } from '@/lib/url/withRedirectedFrom';
import { getServerComponentSupabaseClient } from '@/server/supabase';

import type { ReactNode } from 'react';

export default async function RestaurantSettingsLayout({ children }: { children: ReactNode }) {
  const supabase = await getServerComponentSupabaseClient();
  const {
    data: { user },
    error,
  } = await supabase.auth.getUser();

  if (error) {
    console.error('[settings/restaurant] failed to resolve auth', error.message);
  }

  if (!user) {
    redirect(withRedirectedFrom('/app/auth/signin', '/app/settings/restaurant/profile'));
  }

  return <RestaurantSettingsPageShell>{children}</RestaurantSettingsPageShell>;
}

'use client';

import dynamic from 'next/dynamic';
import { useEffect, type ReactNode } from 'react';

import { OpsEmptyState } from '@/components/features/ops-shell/patterns/OpsEmptyState';
import { Skeleton } from '@/components/ui/skeleton';
import { useOpsActiveMembership, useOpsSession } from '@/contexts/ops-session';

import type { RestaurantSettingsView } from './types';

const SettingsSectionSkeleton = ({ title }: { title: string }) => (
  <div className="rounded-lg border border-border/60 bg-muted/30 p-6" aria-busy="true" role="status">
    <p className="text-sm font-medium text-foreground">{title}</p>
    <div className="mt-3 space-y-3">
      <Skeleton className="h-4 w-40" />
      <Skeleton className="h-10 w-full" />
      <Skeleton className="h-10 w-3/4" />
    </div>
  </div>
);

const RestaurantProfileSection = dynamic(() => import('./RestaurantProfileSection').then((m) => m.RestaurantProfileSection), {
  loading: () => <SettingsSectionSkeleton title="Loading profile" />,
});

const GoogleBusinessProfileSection = dynamic(
  () =>
    import('./google-business-profile/GoogleBusinessProfileSection').then(
      (m) => m.GoogleBusinessProfileSection,
    ),
  {
    loading: () => <SettingsSectionSkeleton title="Loading Google Business Profile" />,
  },
);

const AvailabilityOccasionsCommandCenter = dynamic(
  () =>
    import('./AvailabilityOccasionsCommandCenter').then((m) => m.AvailabilityOccasionsCommandCenter),
  {
    loading: () => <SettingsSectionSkeleton title="Loading availability and occasions" />,
  },
);

const OpsTeamManagementClient = dynamic(() => import('../team').then((m) => m.OpsTeamManagementClient), {
  loading: () => <SettingsSectionSkeleton title="Loading team" />,
});

export type OpsRestaurantSettingsClientProps = {
  defaultRestaurantId?: string | null;
  view: RestaurantSettingsView;
};

export function OpsRestaurantSettingsClient({ defaultRestaurantId, view }: OpsRestaurantSettingsClientProps) {
  const { memberships, activeRestaurantId, setActiveRestaurantId } = useOpsSession();
  const activeMembership = useOpsActiveMembership();

  useEffect(() => {
    if (activeRestaurantId) {
      return;
    }
    if (defaultRestaurantId) {
      setActiveRestaurantId(defaultRestaurantId);
      return;
    }
    if (memberships[0]) {
      setActiveRestaurantId(memberships[0].restaurantId);
    }
  }, [activeRestaurantId, defaultRestaurantId, memberships, setActiveRestaurantId]);

  if (memberships.length === 0) {
    return (
      <section className="mx-auto flex min-h-[60vh] max-w-2xl items-center justify-center p-8">
        <OpsEmptyState
          title="No restaurant access"
          description="You need access to at least one restaurant to manage settings. Contact an owner or admin for access."
        />
      </section>
    );
  }

  const selectedMembership =
    activeMembership ??
    memberships.find((membership) => membership.restaurantId === activeRestaurantId) ??
    memberships[0] ??
    null;

  const selectedRestaurantId = selectedMembership?.restaurantId ?? null;

  const renderByView: Record<RestaurantSettingsView, (context: { restaurantId: string | null }) => ReactNode> = {
    profile: ({ restaurantId }) => <RestaurantProfileSection restaurantId={restaurantId} />,
    'google-business-profile': ({ restaurantId }) => (
      <GoogleBusinessProfileSection restaurantId={restaurantId} />
    ),
    availability: ({ restaurantId }) => <AvailabilityOccasionsCommandCenter restaurantId={restaurantId} />,
    team: () => <OpsTeamManagementClient />,
  };

  return <div className="space-y-6">{renderByView[view]({ restaurantId: selectedRestaurantId })}</div>;
}

'use client';

import { usePathname } from 'next/navigation';
import { useMemo, type ReactNode } from 'react';

import { OpsPageHeader } from '@/components/features/ops-shell/patterns/OpsPageHeader';
import { Badge } from '@/components/ui/badge';
import { useOpsActiveMembership, useOpsSession } from '@/contexts/ops-session';
import { normalizeOpsPathname } from '@/lib/url/opsHref';

import { RestaurantSettingsSubnav } from './RestaurantSettingsSubnav';
import { RESTAURANT_SETTINGS_NAV_ITEMS } from './routes';

export type RestaurantSettingsPageShellProps = {
  /**
   * Override title when rendering outside an authenticated settings route (e.g. dev harness).
   * When omitted, the shell derives the title from the current pathname against the
   * shared restaurant settings navigation metadata.
   */
  title?: string;
  description?: string;
  eyebrow?: string;
  children: ReactNode;
};

const DEFAULT_TITLE = 'Restaurant';
const DEFAULT_DESCRIPTION =
  'Configure the restaurant profile, availability, reservation durations, menu, tables, and team access.';

export function RestaurantSettingsPageShell({
  title,
  description,
  eyebrow = 'Settings',
  children,
}: RestaurantSettingsPageShellProps) {
  const pathname = usePathname();
  const { memberships, activeRestaurantId } = useOpsSession();
  const activeMembership = useOpsActiveMembership();

  const activeNavItem = useMemo(() => {
    if (!pathname) return null;
    const normalized = normalizeOpsPathname(pathname);
    return (
      RESTAURANT_SETTINGS_NAV_ITEMS.find((item) =>
        normalized.startsWith(normalizeOpsPathname(item.href)),
      ) ?? null
    );
  }, [pathname]);

  const resolvedTitle = title ?? activeNavItem?.title ?? DEFAULT_TITLE;
  const resolvedDescription = description ?? activeNavItem?.description ?? DEFAULT_DESCRIPTION;

  const restaurantName =
    activeMembership?.restaurantName ??
    memberships.find((membership) => membership.restaurantId === activeRestaurantId)
      ?.restaurantName ??
    memberships[0]?.restaurantName ??
    null;

  return (
    <main className="mx-auto flex w-full max-w-7xl flex-col gap-6 px-4 py-6 sm:px-6 lg:px-8">
      <OpsPageHeader
        eyebrow={eyebrow}
        title={resolvedTitle}
        subtitle={resolvedDescription}
        meta={
          restaurantName ? (
            <span className="flex flex-wrap items-center gap-2 text-xs text-muted-foreground">
              <span>Editing</span>
              <Badge variant="outline" className="font-medium text-foreground">
                {restaurantName}
              </Badge>
              <span className="hidden sm:inline">
                Use the sidebar restaurant switcher to change restaurants.
              </span>
            </span>
          ) : null
        }
        headingLevel="h1"
        titleClassName="text-3xl"
      />

      <RestaurantSettingsSubnav />

      <div className="pb-8">{children}</div>
    </main>
  );
}

'use client';

import { useQueryClient } from '@tanstack/react-query';
import Link from 'next/link';
import { usePathname } from 'next/navigation';
import { useCallback } from 'react';

import { useOpsServices } from '@/contexts/ops-services';
import { useOpsSession } from '@/contexts/ops-session';
import { prefetchIfStale } from '@/lib/prefetchers';
import { queryKeys } from '@/lib/query/keys';
import { normalizeOpsPathname } from '@/lib/url/opsHref';
import { cn } from '@/lib/utils';

import { RESTAURANT_SETTINGS_NAV_ITEMS } from './routes';

export function RestaurantSettingsSubnav() {
  const pathname = usePathname();
  const queryClient = useQueryClient();
  const { restaurantService, occasionService, teamService, tableInventoryService, menuService } =
    useOpsServices();
  const { activeRestaurantId } = useOpsSession();

  const prefetchSettingsView = useCallback(
    (href: string) => {
      const id = activeRestaurantId;
      if (!id) return;
      switch (normalizeOpsPathname(href)) {
        case '/settings/restaurant/availability':
          return Promise.all([
            prefetchIfStale({
              queryClient,
              queryKey: queryKeys.opsRestaurants.hours(id),
              queryFn: () => restaurantService.getOperatingHours(id),
              enabled: true,
            }),
            prefetchIfStale({
              queryClient,
              queryKey: queryKeys.opsRestaurants.servicePeriods(id),
              queryFn: () => restaurantService.getServicePeriods(id),
              enabled: true,
            }),
            prefetchIfStale({
              queryClient,
              queryKey: queryKeys.opsOccasions.list(),
              queryFn: () => occasionService.listOccasions(),
              enabled: true,
            }),
            prefetchIfStale({
              queryClient,
              queryKey: queryKeys.opsRestaurants.turnBands(id),
              queryFn: () => restaurantService.getTurnBands(id),
              enabled: true,
            }),
          ]);
        case '/settings/restaurant/profile':
          return prefetchIfStale({
            queryClient,
            queryKey: queryKeys.opsRestaurants.detail(id),
            queryFn: () => restaurantService.getProfile(id),
            enabled: true,
          });
        case '/settings/restaurant/google-business-profile':
          return prefetchIfStale({
            queryClient,
            queryKey: queryKeys.opsRestaurants.googleBusinessProfile(id),
            queryFn: () => restaurantService.getGoogleBusinessProfileConnection(id),
            enabled: true,
          });
        case '/settings/restaurant/menu':
          return prefetchIfStale({
            queryClient,
            queryKey: queryKeys.opsMenu.list(id, {}),
            queryFn: () => menuService.listItems(id, {}),
            enabled: true,
          });
        case '/settings/restaurant/team':
          return prefetchIfStale({
            queryClient,
            queryKey: queryKeys.team.invitations(id),
            queryFn: () => teamService.listInvites(id, 'pending'),
            enabled: true,
          });
        case '/settings/restaurant/tables':
          return prefetchIfStale({
            queryClient,
            queryKey: queryKeys.opsTables.list(id, {}),
            queryFn: () => tableInventoryService.list(id),
            enabled: true,
          });
        default:
          return undefined;
      }
    },
    [
      activeRestaurantId,
      menuService,
      occasionService,
      queryClient,
      restaurantService,
      tableInventoryService,
      teamService,
    ],
  );

  return (
    <nav aria-label="Restaurant settings" className="min-w-0">
      <div className="grid min-w-0 grid-cols-1 gap-2 rounded-lg border border-border/60 bg-muted/40 p-1 sm:grid-cols-2 lg:grid-cols-3 2xl:grid-cols-4">
        {RESTAURANT_SETTINGS_NAV_ITEMS.map((item) => {
          const active =
            pathname != null
              ? normalizeOpsPathname(pathname).startsWith(normalizeOpsPathname(item.href))
              : false;
          return (
            <Link
              key={item.href}
              href={item.href}
              aria-current={active ? 'page' : undefined}
              onMouseEnter={() => void prefetchSettingsView(item.href)}
              onFocus={() => void prefetchSettingsView(item.href)}
              className={cn(
                'group flex min-w-0 flex-col gap-1 rounded-md px-3 py-2 text-left text-sm font-medium transition focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background',
                active
                  ? 'bg-background text-foreground shadow-sm ring-1 ring-border'
                  : 'text-muted-foreground hover:text-foreground hover:ring-1 hover:ring-border',
              )}
            >
              <span className="min-w-0 text-wrap leading-5">{item.title}</span>
              <span className="min-w-0 text-wrap text-xs font-normal text-muted-foreground/90">
                {item.description}
              </span>
            </Link>
          );
        })}
      </div>
    </nav>
  );
}

'use client';

import { useCallback, useMemo } from 'react';
import { useState } from 'react';

import {
  AdvancedIdentitySubform,
  BrandIdentitySubform,
  ContactLocationSubform,
  COMMON_TIMEZONES,
  ManagerNotificationsSubform,
  type RestaurantDetailsFormValues,
} from '@/components/ops/restaurants/RestaurantDetailsForm';
import { Alert, AlertDescription, AlertTitle } from '@/components/ui/alert';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { Card, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Skeleton } from '@/components/ui/skeleton';
import { useRegisterOpsUnsavedChanges } from '@/contexts/ops-unsaved-changes';
import { useOpsGoogleBusinessProfileConnection } from '@/hooks/ops/useOpsGoogleBusinessProfile';
import {
  useOpsRestaurantDetails,
  useOpsUpdateRestaurantDetails,
} from '@/hooks/ops/useOpsRestaurantDetails';
import { DEFAULT_RESERVATION_INTERVAL_MINUTES } from '@reserve/shared/config/reservations';

import { deriveProfileVerification } from './google-business-profile/googleBusinessProfileVerification';
import { RestaurantBusinessContextSection } from './RestaurantBusinessContextSection';
import { RestaurantLogoUploader } from './RestaurantLogoUploader';
import { SettingsCard } from './shared/SettingsCard';

const EMPTY_VALUES: RestaurantDetailsFormValues = {
  name: '',
  slug: '',
  timezone: COMMON_TIMEZONES[0],
  contactEmail: null,
  contactPhone: null,
  address: null,
  businessDescription: null,
  managerDailySummaryEnabled: false,
  managerNotificationPhone: null,
  googleMapUrl: null,
  googleReviewUrl: null,
  bookingPolicy: null,
  reservationIntervalMinutes: DEFAULT_RESERVATION_INTERVAL_MINUTES,
  reservationDefaultDurationMinutes: 90,
  reservationLastSeatingBufferMinutes: 15,
  reservationLifecycleGraceMinutes: 15,
};

type RestaurantProfileSectionProps = {
  restaurantId: string | null;
};

type ProfileDirtyKey = 'brand' | 'contact' | 'notifications' | 'advanced';

export function RestaurantProfileSection({ restaurantId }: RestaurantProfileSectionProps) {
  const { data, error, isLoading, refetch } = useOpsRestaurantDetails(restaurantId);
  const gbpConnectionQuery = useOpsGoogleBusinessProfileConnection(restaurantId);
  const updateMutation = useOpsUpdateRestaurantDetails(restaurantId);
  const [dirtyState, setDirtyState] = useState<Record<ProfileDirtyKey, boolean>>({
    brand: false,
    contact: false,
    notifications: false,
    advanced: false,
  });
  const formDirty = Object.values(dirtyState).some(Boolean);

  useRegisterOpsUnsavedChanges(
    'restaurant-profile',
    formDirty,
    'You have unsaved restaurant profile changes. Leave without saving them?',
  );

  const initialValues = useMemo<RestaurantDetailsFormValues>(() => {
    if (!data) {
      return EMPTY_VALUES;
    }

    return {
      name: data.name,
      slug: data.slug ?? '',
      timezone: data.timezone ?? COMMON_TIMEZONES[0],
      contactEmail: data.contactEmail,
      contactPhone: data.contactPhone,
      address: data.address,
      businessDescription: data.businessDescription,
      managerDailySummaryEnabled: data.managerDailySummaryEnabled,
      managerNotificationPhone: data.managerNotificationPhone,
      googleMapUrl: data.googleMapUrl,
      googleReviewUrl: data.googleReviewUrl,
      bookingPolicy: data.bookingPolicy,
      reservationIntervalMinutes: data.reservationIntervalMinutes,
      reservationDefaultDurationMinutes: data.reservationDefaultDurationMinutes,
      reservationLastSeatingBufferMinutes: data.reservationLastSeatingBufferMinutes,
      reservationLifecycleGraceMinutes: data.reservationLifecycleGraceMinutes,
    };
  }, [data]);

  const derivedRestaurantName = data?.name ?? initialValues.name ?? 'Restaurant';
  const profileVerification = useMemo(
    () =>
      deriveProfileVerification({
        profile: data,
        connection: gbpConnectionQuery.data,
      }),
    [data, gbpConnectionQuery.data],
  );
  const setSubformDirty = useCallback(
    (key: ProfileDirtyKey) => (dirty: boolean) => {
      setDirtyState((current) => (current[key] === dirty ? current : { ...current, [key]: dirty }));
    },
    [],
  );

  if (!restaurantId) {
    return (
      <SettingsCard
        title="Restaurant profile"
        description="Select a restaurant to manage what guests and staff see."
      >
        <p className="text-sm text-muted-foreground">
          Choose a restaurant using the sidebar switcher to update its public details and team
          alerts.
        </p>
      </SettingsCard>
    );
  }

  if (isLoading && !data) {
    return (
      <SettingsCard
        title="Restaurant profile"
        description="Loading the restaurant details staff use day to day."
      >
        <div className="space-y-4">
          <Skeleton className="h-6 w-40" />
          <Skeleton className="h-24 w-full" />
        </div>
      </SettingsCard>
    );
  }

  if (error) {
    return (
      <SettingsCard
        title="Restaurant profile"
        description="Update public details and team alerts."
      >
        <Alert variant="destructive">
          <AlertTitle>Unable to load restaurant details</AlertTitle>
          <AlertDescription className="flex items-center justify-between gap-4">
            <span>{error.message}</span>
            <Button type="button" variant="outline" size="sm" onClick={() => refetch()}>
              Retry
            </Button>
          </AlertDescription>
        </Alert>
      </SettingsCard>
    );
  }

  return (
    <div className="flex flex-col gap-6">
      <Card className="border-border/70">
        <CardHeader className="gap-4 sm:flex-row sm:items-end sm:justify-between sm:space-y-0">
          <div className="flex flex-col gap-2">
            <Badge
              variant={profileVerification.warnings.length > 0 ? 'secondary' : 'outline'}
              className="w-fit"
            >
              {profileVerification.summary}
            </Badge>
            <div className="flex flex-col gap-1">
              <CardTitle className="text-2xl">Restaurant profile</CardTitle>
              <CardDescription className="max-w-3xl">
                Keep guest-facing details, team alerts, and public discovery information in one
                place.
              </CardDescription>
            </div>
          </div>
          <Button type="button" variant="outline" asChild>
            <a href="/app/settings/restaurant/google-business-profile">Review Google changes</a>
          </Button>
        </CardHeader>
      </Card>

      <div id="profile-identity" className="scroll-mt-28">
        <SettingsCard
          title="Brand and public description"
          description="Set the name, logo, and short description guests should recognise."
        >
          <div className="flex flex-col gap-6">
            <RestaurantLogoUploader
              restaurantId={restaurantId}
              restaurantName={derivedRestaurantName}
              logoUrl={data?.logoUrl ?? null}
              updateMutation={updateMutation}
              isLoading={isLoading && !data}
            />
            <BrandIdentitySubform
              restaurantId={restaurantId}
              initialValues={initialValues}
              onDirtyChange={setSubformDirty('brand')}
              gbpFieldVerifications={profileVerification.fields}
            />
          </div>
        </SettingsCard>
      </div>

      <SettingsCard
        title="Contact and location"
        description="Keep the public phone, email, address, directions, and review links current."
      >
        <ContactLocationSubform
          restaurantId={restaurantId}
          initialValues={initialValues}
          onDirtyChange={setSubformDirty('contact')}
          gbpFieldVerifications={profileVerification.fields}
        />
      </SettingsCard>

      <div id="profile-notifications" className="scroll-mt-28">
        <SettingsCard
          title="Daily manager summary"
          description="Choose where the daily booking summary SMS should go."
        >
          <ManagerNotificationsSubform
            restaurantId={restaurantId}
            initialValues={initialValues}
            onDirtyChange={setSubformDirty('notifications')}
          />
        </SettingsCard>
      </div>

      <div id="profile-discovery" className="scroll-mt-28">
        <SettingsCard
          title="Guest discovery essentials"
          description="Set the profile basics, dining categories, and public links guests use when discovering this restaurant."
        >
          <RestaurantBusinessContextSection restaurantId={restaurantId} embedded />
        </SettingsCard>
      </div>

      <div id="profile-advanced" className="scroll-mt-28">
        <SettingsCard
          title="Booking link"
          description="Edit the short link used in guest booking URLs."
        >
          <AdvancedIdentitySubform
            restaurantId={restaurantId}
            initialValues={initialValues}
            onDirtyChange={setSubformDirty('advanced')}
          />
        </SettingsCard>
      </div>
    </div>
  );
}

'use client';

import { Check, ChevronsUpDown } from 'lucide-react';
import { useEffect, useMemo, useState } from 'react';

import { GoogleBusinessProfileComparisonBadge } from '@/components/features/restaurant-settings/GoogleBusinessProfileComparisonBadge';
import { HelpTooltip } from '@/components/features/restaurant-settings/HelpTooltip';
import {
  Accordion,
  AccordionContent,
  AccordionItem,
  AccordionTrigger,
} from '@/components/ui/accordion';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Popover, PopoverContent, PopoverTrigger } from '@/components/ui/popover';
import { ScrollArea } from '@/components/ui/scroll-area';
import { Switch } from '@/components/ui/switch';
import { Textarea } from '@/components/ui/textarea';
import { TooltipProvider } from '@/components/ui/tooltip';
import { useOpsUpdateRestaurantDetails } from '@/hooks/ops/useOpsRestaurantDetails';
import {
  RESERVATION_INTERVAL_MAX,
  RESERVATION_INTERVAL_MIN,
} from '@/lib/restaurants/reservation-interval';
import { cn } from '@/lib/utils';

import type { UpdateRestaurantInput } from '@/app/api/ops/restaurants/schema';
import type { ProfileFieldVerification } from '@/components/features/restaurant-settings/google-business-profile/googleBusinessProfileVerification';
import type { RestaurantProfile } from '@/services/ops/restaurants';
import type { PropsWithChildren } from 'react';

export type RestaurantDetailsFormValues = {
  name: string;
  slug: string;
  timezone: string;
  contactEmail: string | null;
  contactPhone: string | null;
  address: string | null;
  businessDescription: string | null;
  managerDailySummaryEnabled: boolean;
  managerNotificationPhone: string | null;
  googleMapUrl: string | null;
  googleReviewUrl: string | null;
  bookingPolicy: string | null;
  reservationIntervalMinutes: number;
  reservationDefaultDurationMinutes: number;
  reservationLastSeatingBufferMinutes: number;
  reservationLifecycleGraceMinutes: number;
};

export type RestaurantDetailsFormProps = PropsWithChildren<{
  initialValues: RestaurantDetailsFormValues;
  onSubmit: (values: UpdateRestaurantInput) => Promise<void> | void;
  isSubmitting?: boolean;
  onCancel?: () => void;
  onDirtyChange?: (dirty: boolean) => void;
  submitLabel?: string;
  className?: string;
  gbpFieldVerifications?: Partial<Record<GbpComparableField, ProfileFieldVerification>>;
}>;

type FormState = {
  name: string;
  slug: string;
  timezone: string;
  contactEmail: string;
  contactPhone: string;
  address: string;
  businessDescription: string;
  managerDailySummaryEnabled: boolean;
  managerNotificationPhone: string;
  googleMapUrl: string;
  googleReviewUrl: string;
  bookingPolicy: string;
  reservationIntervalMinutes: string;
  reservationDefaultDurationMinutes: string;
  reservationLastSeatingBufferMinutes: string;
  reservationLifecycleGraceMinutes: string;
};

type FormErrors = Partial<Record<keyof FormState, string>>;
type GbpComparableField =
  | 'name'
  | 'businessDescription'
  | 'contactPhone'
  | 'address'
  | 'googleMapUrl'
  | 'googleReviewUrl';
type GbpFieldStatus = 'verified' | 'drifted' | 'unavailable';

const SLUG_PATTERN = /^[a-z0-9]+(-[a-z0-9]+)*$/;

const FIELD_TOOLTIPS = {
  slug: 'Lowercase text used in booking links. Only letters, numbers, and hyphens are allowed.',
  timezone:
    'Keeps opening hours, reservations, and reminders aligned to the restaurant’s local time.',
  businessDescription:
    'Public copy guests may see when they find or book this restaurant. Keep it clear and current.',
  reservationInterval:
    'Spacing between available reservation slots. Shorter intervals create more options but increase booking traffic.',
  reservationDuration:
    'Default dining time that pre-fills new reservations. Staff can override per booking if needed.',
  lastSeatingBuffer:
    'Minutes before closing when you stop seating guests so everyone can finish before the kitchen closes.',
  lifecycleGrace:
    'Minutes after the reservation end time when staff can still check out or mark no-shows.',
  bookingPolicy:
    'Optional message shown to guests during booking and in confirmations (e.g., grace periods, large-party policies).',
  managerNotificationPhone:
    'Direct delivery number for the daily manager SMS summary. Use E.164 format such as +447700900000.',
  managerDailySummaryEnabled:
    'Turns the 10:00 local-time manager booking summary SMS on or off for this restaurant.',
  googleReviewUrl:
    'Link for customers to leave a Google review. This is sent in post-visit emails.',
  googleMapUrl: 'Link shared with guests for directions in Google Maps.',
} as const;

export const COMMON_TIMEZONES = [
  'Europe/London',
  'America/New_York',
  'America/Chicago',
  'America/Denver',
  'America/Los_Angeles',
  'Asia/Tokyo',
  'Asia/Shanghai',
  'Australia/Sydney',
  'Europe/Paris',
  'Europe/Berlin',
] as const;

const ALL_TIMEZONES =
  typeof Intl.supportedValuesOf === 'function'
    ? Intl.supportedValuesOf('timeZone')
    : [...COMMON_TIMEZONES];

function normalizeWhitespace(value: string): string {
  return value.replace(/\s+/g, ' ').trim();
}

function normalizeComparableText(value: string | null | undefined): string | null {
  if (typeof value !== 'string') {
    return null;
  }

  const normalized = normalizeWhitespace(value).toLowerCase();
  return normalized.length > 0 ? normalized : null;
}

function normalizeComparablePhone(value: string | null | undefined): string | null {
  if (typeof value !== 'string') {
    return null;
  }

  const normalized = value.replace(/[^\d+]/g, '');
  return normalized.length > 0 ? normalized : null;
}

function normalizeComparableUrl(value: string | null | undefined): string | null {
  if (typeof value !== 'string') {
    return null;
  }

  const trimmed = value.trim();
  if (!trimmed) {
    return null;
  }

  try {
    const parsed = new URL(trimmed);
    const normalizedPath = parsed.pathname.replace(/\/+$/, '') || '/';
    return `${parsed.protocol.toLowerCase()}//${parsed.host.toLowerCase()}${normalizedPath}${parsed.search}`;
  } catch {
    return trimmed.toLowerCase();
  }
}

function compareFieldValue(
  field: GbpComparableField,
  currentValue: string,
  gbpValue: string | null | undefined,
): boolean {
  switch (field) {
    case 'contactPhone': {
      const currentPhone = normalizeComparablePhone(currentValue);
      const providerPhone = normalizeComparablePhone(gbpValue);
      return Boolean(currentPhone) && currentPhone === providerPhone;
    }
    case 'googleMapUrl':
    case 'googleReviewUrl': {
      const currentUrl = normalizeComparableUrl(currentValue);
      const providerUrl = normalizeComparableUrl(gbpValue);
      return Boolean(currentUrl) && currentUrl === providerUrl;
    }
    case 'name':
    case 'businessDescription':
    case 'address': {
      const currentText = normalizeComparableText(currentValue);
      const providerText = normalizeComparableText(gbpValue);
      return Boolean(currentText) && currentText === providerText;
    }
    default:
      return false;
  }
}

function GbpStatusBadge(props: {
  verification?: ProfileFieldVerification;
  status: GbpFieldStatus;
}) {
  if (props.status === 'unavailable' || !props.verification) {
