                                  id={makeFieldId('attributes', row.id, field)}
                                  value={row[field as keyof AttributeEditor] as string}
                                  rows={5}
                                  onChange={(event) => {
                                    setAttributes((current) =>
                                      current.map((item) =>
                                        item.id === row.id
                                          ? { ...item, [field]: event.target.value }
                                          : item,
                                      ),
                                    );
                                    markDirty('attributes');
                                  }}
                                />
                              </div>
                            ))}
                          </div>
                        </div>
                      </div>
