                      uriValue: '',
                      uriValuesText: '',
                      enumValuesText: '',
                      unsetEnumValuesText: '',
                      rawValueJson: '',
                      rawEnumValuesJson: '',
                      displayValueJson: '',
                      valueMetadataJson: '',
