                disabled={!dirty.serviceItems || savingFamily === 'serviceItems'}
              >
                Save service items
              </Button>
            </div>
            {errors.serviceItems ? (
              <p className="text-sm text-destructive">{errors.serviceItems}</p>
            ) : null}
          </DiscoveryFamilyPanel>
        </DiscoveryPanelsFrame>
      </div>
    ),
  });
}

