}

import { isReservationTime, normalizeTime as normalizeReservationTime } from '@reserve/shared/time';
import { runtime } from '@shared/config/runtime';

import type { ReservationTime } from '@reserve/shared/time';

export type ReservationConfig = {
  timezone: string;
  opening: {
    open: ReservationTime;
    close: ReservationTime;
    intervalMinutes: number;
  };
  windows: {
    weekdayLunchEnd: ReservationTime;
    weekendLunchEnd: ReservationTime;
    dinnerStart: ReservationTime;
    happyHour?: {
      start: ReservationTime;
      end: ReservationTime;
    };
  };
  defaultDurationMinutes: number;
  copy: {
    unavailableTooltip: string;
  };
};

export type ReservationConfigIssue = {
  key: string;
  value: string;
  reason: string;
};

type MutableReservationConfig = {
  config: ReservationConfig;
  issues: ReservationConfigIssue[];
};

export const DEFAULT_RESERVATION_INTERVAL_MINUTES = 30;

const DEFAULT_RESERVATION_CONFIG: ReservationConfig = {
  timezone: 'Europe/London',
  opening: {
    open: '12:00' as ReservationTime,
    close: '23:00' as ReservationTime,
    intervalMinutes: DEFAULT_RESERVATION_INTERVAL_MINUTES,
  },
  windows: {
    weekdayLunchEnd: '15:00' as ReservationTime,
    weekendLunchEnd: '17:00' as ReservationTime,
    dinnerStart: '17:00' as ReservationTime,
    happyHour: {
      start: '15:00' as ReservationTime,
      end: '17:00' as ReservationTime,
    },
  },
  defaultDurationMinutes: 90,
  copy: {
    unavailableTooltip: 'Not available for the selected time.',
  },
};

const timeOverrideKeys = {
  open: 'RESERVE_RESERVATION_OPEN',
  close: 'RESERVE_RESERVATION_CLOSE',
  interval: 'RESERVE_RESERVATION_INTERVAL_MINUTES',
  weekdayLunchEnd: 'RESERVE_RESERVATION_WEEKDAY_LUNCH_END',
  weekendLunchEnd: 'RESERVE_RESERVATION_WEEKEND_LUNCH_END',
  dinnerStart: 'RESERVE_RESERVATION_DINNER_START',
  happyHourStart: 'RESERVE_RESERVATION_HAPPY_HOUR_START',
  happyHourEnd: 'RESERVE_RESERVATION_HAPPY_HOUR_END',
  duration: 'RESERVE_RESERVATION_DEFAULT_DURATION_MINUTES',
  timezone: 'RESERVE_RESERVATION_TIMEZONE',
  tooltip: 'RESERVE_RESERVATION_UNAVAILABLE_TOOLTIP',
} as const;

const normalizeTimeOverride = (
  key: string,
  fallback: ReservationTime,
  issues: ReservationConfigIssue[],
): ReservationTime => {
  const raw = runtime.readString(key);
  if (!raw) return fallback;
  const candidate = normalizeReservationTime(raw);
  if (!candidate || !isReservationTime(candidate)) {
    issues.push({
      key,
      value: raw,
      reason: 'Expected HH:MM 24-hour format',
    });
    return fallback;
  }
  return candidate;
};

const readIntervalOverride = (
  key: string,
  fallback: number,
  issues: ReservationConfigIssue[],
): number => {
  const raw = runtime.readNumber(key);
  if (raw === undefined) return fallback;
  if (!Number.isFinite(raw) || raw <= 0 || raw > 180) {
    issues.push({
      key,
      value: String(raw),
      reason: 'Interval must be between 1 and 180 minutes',
    });
    return fallback;
  }
  return raw;
};

const readDurationOverride = (
  key: string,
  fallback: number,
  issues: ReservationConfigIssue[],
): number => {
  const raw = runtime.readNumber(key);
  if (raw === undefined) return fallback;
  if (!Number.isFinite(raw) || raw < 15 || raw > 300) {
    issues.push({
      key,
      value: String(raw),
      reason: 'Duration must be between 15 and 300 minutes',
    });
    return fallback;
  }
  return raw;
};

const applyOverrides = (): MutableReservationConfig => {
  const issues: ReservationConfigIssue[] = [];
  const base = structuredClone(DEFAULT_RESERVATION_CONFIG);

  base.opening.open = normalizeTimeOverride(timeOverrideKeys.open, base.opening.open, issues);
  base.opening.close = normalizeTimeOverride(timeOverrideKeys.close, base.opening.close, issues);
  base.opening.intervalMinutes = readIntervalOverride(
    timeOverrideKeys.interval,
    base.opening.intervalMinutes,
    issues,
  );

  base.windows.weekdayLunchEnd = normalizeTimeOverride(
    timeOverrideKeys.weekdayLunchEnd,
    base.windows.weekdayLunchEnd,
    issues,
  );
  base.windows.weekendLunchEnd = normalizeTimeOverride(
    timeOverrideKeys.weekendLunchEnd,
    base.windows.weekendLunchEnd,
    issues,
  );
  base.windows.dinnerStart = normalizeTimeOverride(
    timeOverrideKeys.dinnerStart,
    base.windows.dinnerStart,
    issues,
  );

  const happyHourStart = normalizeTimeOverride(
    timeOverrideKeys.happyHourStart,
    base.windows.happyHour?.start ?? base.windows.dinnerStart,
    issues,
  );
  const happyHourEnd = normalizeTimeOverride(
    timeOverrideKeys.happyHourEnd,
    base.windows.happyHour?.end ?? base.windows.dinnerStart,
    issues,
  );

  if (base.windows.happyHour) {
    base.windows.happyHour = { start: happyHourStart, end: happyHourEnd };
  }

  const duration = readDurationOverride(
    timeOverrideKeys.duration,
    base.defaultDurationMinutes,
    issues,
  );
  base.defaultDurationMinutes = duration;

  const timezoneOverride = runtime.readString(timeOverrideKeys.timezone);
  if (timezoneOverride) {
    base.timezone = timezoneOverride.trim();
  }

  const tooltipOverride = runtime.readString(timeOverrideKeys.tooltip);
  if (tooltipOverride) {
    base.copy.unavailableTooltip = tooltipOverride.trim();
  }

  const openMinutes =
    parseInt(base.opening.open.slice(0, 2), 10) * 60 + parseInt(base.opening.open.slice(3), 10);
  const closeMinutes =
    parseInt(base.opening.close.slice(0, 2), 10) * 60 + parseInt(base.opening.close.slice(3), 10);

  if (closeMinutes <= openMinutes) {
    issues.push({
      key: `${timeOverrideKeys.open}/${timeOverrideKeys.close}`,
      value: `${base.opening.open}-${base.opening.close}`,
      reason: 'Close time must be after open time',
    });
  }

  return { config: base, issues };
};

export type ReservationConfigResult = MutableReservationConfig;

export const reservationConfigResult: ReservationConfigResult = applyOverrides();

if (reservationConfigResult.issues.length > 0 && runtime.isDev) {
  console.warn(
    '[reserve config] Using default reservation config due to issues:',
    reservationConfigResult.issues,
  );
}

export const defaultReservationConfig = reservationConfigResult.config;

const metaEnv = (import.meta as unknown as { env?: Record<string, string | boolean | undefined> })
  .env;
const processEnv =
  typeof process !== 'undefined' ? (process.env as Record<string, string | undefined>) : undefined;

type ReadOptions = {
  fallback?: string;
  alternatives?: string[];
};

type BooleanOptions = Omit<ReadOptions, 'fallback'> & {
  fallback?: boolean;
};

type NumberOptions = Omit<ReadOptions, 'fallback'> & {
  fallback?: number;
};

const toBooleanString = (value: string | boolean | undefined): string | undefined => {
  if (typeof value === 'string') return value;
  if (typeof value === 'boolean') return value ? 'true' : 'false';
  return undefined;
};

const expandCandidate = (candidate: string): string[] => {
  const normalized = candidate.trim();
  if (normalized.length === 0) return [];
  if (normalized.startsWith('VITE_') || normalized.startsWith('NEXT_PUBLIC_')) {
    const bare = normalized.replace(/^(VITE_|NEXT_PUBLIC_)/, '');
    return [normalized, bare];
  }
  return [normalized, `VITE_${normalized}`, `NEXT_PUBLIC_${normalized}`];
};

const collectCandidates = (key: string, alternatives?: string[]): string[] => {
  const set = new Set<string>();
  [key, ...(alternatives ?? [])].forEach((candidate) => {
    expandCandidate(candidate).forEach((entry) => {
      if (entry) set.add(entry);
    });
  });
  return Array.from(set);
};

const readRaw = (key: string, options?: ReadOptions): string | undefined => {
  const candidates = collectCandidates(key, options?.alternatives);

  for (const candidate of candidates) {
    const fromMeta = toBooleanString(metaEnv?.[candidate]);
    if (typeof fromMeta === 'string') {
      return fromMeta;
    }
    const fromProcess = processEnv?.[candidate];
    if (typeof fromProcess === 'string' && fromProcess.length > 0) {
      return fromProcess;
    }
  }

  return options?.fallback;
};

const parseBoolean = (value: string | undefined): boolean | undefined => {
  if (typeof value !== 'string') return undefined;
  if (/^(true|1|yes)$/i.test(value.trim())) return true;
  if (/^(false|0|no)$/i.test(value.trim())) return false;
  return undefined;
};

const parseNumber = (value: string | undefined): number | undefined => {
  if (typeof value !== 'string') return undefined;
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : undefined;
};

const resolvedMode = readRaw('MODE', { alternatives: ['NODE_ENV'] }) ?? 'production';

export const runtime = {
  mode: resolvedMode,
  isDev: resolvedMode === 'development',
  isTest: resolvedMode === 'test',
  readString: (key: string, options?: ReadOptions): string | undefined => readRaw(key, options),
  readBoolean: (key: string, options?: BooleanOptions): boolean | undefined => {
    const value = readRaw(key, options ? { alternatives: options.alternatives } : undefined);
    const parsed = parseBoolean(value);
    return parsed ?? options?.fallback;
  },
  readNumber: (key: string, options?: NumberOptions): number | undefined => {
    const value = readRaw(key, options ? { alternatives: options.alternatives } : undefined);
    const parsed = parseNumber(value);
    return parsed ?? options?.fallback;
  },
};

export type Runtime = typeof runtime;

import { z } from 'zod';

import { normalizeTime, toMinutes } from '@reserve/shared/time';

export type OccasionKey = string;
const DATE_REGEX = /^\d{4}-\d{2}-\d{2}$/;

export const occasionAvailabilityRuleSchema = z.discriminatedUnion('kind', [
  z.object({
    kind: z.literal('anytime') as z.ZodLiteral<'anytime'>,
  }),
  z.object({
    kind: z.literal('time_window') as z.ZodLiteral<'time_window'>,
    start: z.string().min(1),
    end: z.string().min(1),
  }),
  z.object({
    kind: z.literal('month_only') as z.ZodLiteral<'month_only'>,
    months: z.array(z.number().int().min(1).max(12)).min(1),
  }),
  z.object({
    kind: z.literal('date_range') as z.ZodLiteral<'date_range'>,
    start: z.string().regex(DATE_REGEX),
    end: z.string().regex(DATE_REGEX),
  }),
  z.object({
    kind: z.literal('specific_dates') as z.ZodLiteral<'specific_dates'>,
    dates: z.array(z.string().regex(DATE_REGEX)).min(1),
  }),
]);

export type OccasionAvailabilityRule = z.infer<typeof occasionAvailabilityRuleSchema>;

export type OccasionDefinition = {
  key: OccasionKey;
  label: string;
  shortLabel: string;
  description: string | null;
  availability: OccasionAvailabilityRule[];
  defaultDurationMinutes: number;
  displayOrder: number;
  isActive: boolean;
};

export type RawOccasionRow = {
  key: string;
  label: string;
  short_label?: string | null;
  description?: string | null;
  availability?: unknown;
  default_duration_minutes?: number | null;
  display_order?: number | null;
  is_active?: boolean | null;
};

const ensureTime = (value: string): string | null => {
  const normalized = normalizeTime(value);
  if (!normalized) return null;
  return normalized;
};

const sanitizeRule = (rule: OccasionAvailabilityRule): OccasionAvailabilityRule | null => {
  switch (rule.kind) {
    case 'anytime':
      return rule;
    case 'time_window': {
      const start = ensureTime(rule.start);
      const end = ensureTime(rule.end);
      if (!start || !end) {
        return null;
      }
      if (toMinutes(end) <= toMinutes(start)) {
        return null;
      }
      return { kind: 'time_window', start, end };
    }
    case 'month_only': {
      const months = Array.from(
        new Set(rule.months.filter((month) => month >= 1 && month <= 12)),
      ).sort((a, b) => a - b);
      if (months.length === 0) {
        return null;
      }
      return { kind: 'month_only', months };
    }
    case 'date_range': {
      const { start, end } = rule;
      if (!DATE_REGEX.test(start) || !DATE_REGEX.test(end)) {
        return null;
      }
      if (start > end) {
        return { kind: 'date_range', start: end, end: start };
      }
      return rule;
    }
    case 'specific_dates': {
      const dates = Array.from(new Set(rule.dates.filter((date) => DATE_REGEX.test(date)))).sort();
      if (dates.length === 0) {
        return null;
      }
      return { kind: 'specific_dates', dates };
    }
    default:
      return null;
  }
};

const toAvailability = (value: unknown): OccasionAvailabilityRule[] => {
  if (!value) {
    return [];
  }
  try {
    const parsed = Array.isArray(value)
      ? value
      : typeof value === 'string'
        ? JSON.parse(value)
        : [];
    if (!Array.isArray(parsed)) {
      return [];
    }
    const result: OccasionAvailabilityRule[] = [];
    for (const entry of parsed) {
      const candidate = occasionAvailabilityRuleSchema.safeParse(entry);
      if (!candidate.success) {
        continue;
      }
      const sanitized = sanitizeRule(candidate.data);
      if (sanitized) {
        result.push(sanitized);
      }
    }
    return result;
  } catch (error) {
    if (process.env.NODE_ENV !== 'production') {
      console.warn('[occasions] failed to parse availability', { value, error });
    }
    return [];
  }
};

export function toOccasionDefinition(row: RawOccasionRow): OccasionDefinition {
  const trimmedKey = row.key?.trim();
  if (!trimmedKey) {
    throw new Error('Occasion key is required');
  }
  const trimmedLabel = row.label?.trim() ?? trimmedKey;
  const shortLabelRaw = row.short_label?.trim();
  const availability = toAvailability(row.availability);
  const defaultDurationMinutes =
    row.default_duration_minutes && Number.isFinite(row.default_duration_minutes)
      ? Math.max(1, Math.floor(row.default_duration_minutes))
      : 90;
  const displayOrder =
    row.display_order && Number.isFinite(row.display_order) ? Math.floor(row.display_order) : 0;
  const isActive = row.is_active ?? true;

  return {
    key: trimmedKey,
    label: trimmedLabel,
    shortLabel: shortLabelRaw && shortLabelRaw.length > 0 ? shortLabelRaw : trimmedLabel,
    description: row.description ?? null,
    availability,
    defaultDurationMinutes,
    displayOrder,
    isActive,
  } satisfies OccasionDefinition;
}

export function sortOccasions(definitions: OccasionDefinition[]): OccasionDefinition[] {
  return [...definitions].sort((a, b) => {
    if (a.displayOrder !== b.displayOrder) {
      return a.displayOrder - b.displayOrder;
    }
    return a.label.localeCompare(b.label);
  });
}

export type OccasionCatalog = {
  definitions: OccasionDefinition[];
  byKey: Map<OccasionKey, OccasionDefinition>;
  orderedKeys: OccasionKey[];
};

export function toOccasionCatalog(definitions: OccasionDefinition[]): OccasionCatalog {
  const active = definitions.filter((definition) => definition.isActive);
  const sorted = sortOccasions(active);
  const byKey = new Map<OccasionKey, OccasionDefinition>();
  const orderedKeys: OccasionKey[] = [];
  for (const definition of sorted) {
    byKey.set(definition.key, definition);
    orderedKeys.push(definition.key);
  }
  return { definitions: sorted, byKey, orderedKeys };
}

export function getFallbackOccasionCatalog(): OccasionCatalog {
  return toOccasionCatalog([]);
}

export type OccasionAvailabilityContext = {
  date: string;
  time?: string | null;
  timezone: string;
  month?: number;
};

const getMonthInTimezone = (date: string, timezone: string): number => {
  try {
    const reference = new Date(`${date}T12:00:00Z`);
    const formatter = new Intl.DateTimeFormat('en-US', { month: 'numeric', timeZone: timezone });
    const month = Number.parseInt(formatter.format(reference), 10);
    if (Number.isFinite(month)) {
      return month;
    }
  } catch (error) {
    if (process.env.NODE_ENV !== 'production') {
      console.warn('[occasions] failed to resolve month', { date, timezone, error });
    }
  }
  const fallback = new Date(`${date}T00:00:00Z`);
  return fallback.getUTCMonth() + 1;
};

const isWithinTimeWindow = (
  time: string | null | undefined,
  rule: Extract<OccasionAvailabilityRule, { kind: 'time_window' }>,
): boolean => {
  if (!time) {
    return true;
  }
  const normalized = normalizeTime(time);
  if (!normalized) {
    return false;
  }
  const target = toMinutes(normalized);
  return target >= toMinutes(rule.start) && target < toMinutes(rule.end);
};

export function isOccasionAvailable(
  definition: OccasionDefinition,
  context: OccasionAvailabilityContext,
): boolean {
  if (!definition.isActive) {
    return false;
  }
  if (definition.availability.length === 0) {
    return true;
  }
  return definition.availability.every((rule) => {
    switch (rule.kind) {
      case 'anytime':
        return true;
      case 'time_window':
        return isWithinTimeWindow(context.time ?? null, rule);
      case 'month_only': {
        const month = context.month ?? getMonthInTimezone(context.date, context.timezone);
        return rule.months.includes(month);
      }
      case 'date_range':
        return context.date >= rule.start && context.date <= rule.end;
      case 'specific_dates':
        return rule.dates.includes(context.date);
      default:
        return true;
    }
  });
}

export function coerceOccasionKey(
  options: OccasionCatalog,
  candidate: OccasionKey | null | undefined,
  fallback?: OccasionKey,
): OccasionKey {
  if (candidate && options.byKey.has(candidate)) {
    return candidate;
  }
  if (fallback && options.byKey.has(fallback)) {
    return fallback;
  }
  return options.orderedKeys[0] ?? fallback ?? 'dinner';
}

import { toMinutes } from './time';
